  function decodeBase64(value) {
    if (typeof atob === "function") {
      const binary = atob(value);
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
      return bytes;
    }
    if (typeof Buffer !== "undefined") return Uint8Array.from(Buffer.from(value, "base64"));
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const bytes = []; let buffer = 0; let bits = 0;
    for (const character of value) {
      if (character === "=") break;
      const digit = alphabet.indexOf(character);
      if (digit < 0) continue;
      buffer = (buffer << 6) | digit; bits += 6;
      if (bits >= 8) { bits -= 8; bytes.push((buffer >> bits) & 255); }
    }
    return Uint8Array.from(bytes);
  }

  function decodeRle(value) {
    const encoded = decodeBase64(value);
    const result = new Uint8Array(WIDTH * HEIGHT);
    let source = 0; let target = 0;
    while (source < encoded.length) {
      let count = 0; let shift = 0;
      do {
        if (source >= encoded.length || shift > 28) throw new Error("Malformed field navigation RLE");
        const byte = encoded[source++]; count |= (byte & 127) << shift; shift += 7;
        if (!(byte & 128)) break;
      } while (true);
      if (!count || source >= encoded.length || target + count > result.length) throw new Error("Invalid field navigation RLE span");
      result.fill(encoded[source++], target, target + count); target += count;
    }
    if (target !== result.length) throw new Error("Incomplete field navigation RLE");
    return result;
  }

  return Object.freeze({
    package: PACKAGE,
    width: WIDTH,
    height: HEIGHT,
    maskValuesValidated: true,
    masks: Object.freeze({
      white: decodeRle(MASK_RLE.white),
      magenta: decodeRle(MASK_RLE.magenta),
      cyan: decodeRle(MASK_RLE.cyan),
    }),
  });
